1	// Raspberry Pi Camera Module 3 — gate camera node configuration.
2	// URLs come from Vite env (VITE_PI_CAMERA_STREAM_URL / VITE_PI_CAMERA_SNAPSHOT_URL)
3	// with demo-network fallbacks so the kiosk works out of the box.
4	
5	export const PI_CAMERA_STREAM_URL =
6	  import.meta.env.VITE_PI_CAMERA_STREAM_URL || "http://172.20.10.4:8081/video_feed";
7	
8	export const PI_CAMERA_SNAPSHOT_URL =
9	  import.meta.env.VITE_PI_CAMERA_SNAPSHOT_URL || "http://172.20.10.4:8081/snapshot";
10	
11	export const CAMERA_SOURCES = {
12	  PI: "pi",
13	  WEBCAM: "webcam",
14	};
15	
16	export const CAMERA_STATUS_MESSAGES = {
17	  PI_CONNECTED: "Pi Gate Camera connected",
18	  PI_UNAVAILABLE: "Pi Camera unavailable — using laptop webcam fallback",
19	  WEBCAM_ACTIVE: "Laptop webcam active",
20	};
21	
22	/**
23	 * Probe the Pi snapshot endpoint to decide if the gate camera is reachable.
24	 * Any network error, CORS block, or timeout counts as unreachable so the
25	 * caller can fall back to the laptop webcam.
26	 */
27	export async function isPiCameraReachable(timeoutMs = 3500) {
28	  try {
29	    const controller = new AbortController();
30	    const timer = setTimeout(() => controller.abort(), timeoutMs);
31	    const res = await fetch(`${PI_CAMERA_SNAPSHOT_URL}?probe=${Date.now()}`, {
32	      cache: "no-store",
33	      signal: controller.signal,
34	    });
35	    clearTimeout(timer);
36	    return res.ok;
37	  } catch {
38	    return false;
39	  }
40	}
41	
42	/**
43	 * Fetch one frame from the Pi snapshot endpoint as an ImageBitmap that can be
44	 * drawn onto the existing capture canvas (blob-backed, so the canvas is not
45	 * tainted and toDataURL keeps working for the recognition API).
46	 */
47	export async function fetchPiSnapshotBitmap(timeoutMs = 4000) {
48	  const controller = new AbortController();
