391	        const requester = await User.findByPk(req.user.id);
392	        if (!requester || requester.isActive === false) {
393	            return res.status(403).json({ error: "Account is inactive or no longer exists." });
394	        }
395	
396	        const requestedUserId = targetUserId || req.user.id;
397	        const isSelfEnrollment = String(requestedUserId) === String(req.user.id);
398	
399	        if (!isSelfEnrollment && requester.role !== 'FM') {
400	            return res.status(403).json({ error: "Only Facilities Managers can re-enroll another user's Face ID." });
401	        }
402	
403	        const targetUser = await User.findByPk(requestedUserId);
404	        if (!targetUser) {
405	            return res.status(404).json({ error: "Target user not found." });
406	        }
407	
408	        console.log(`Starting face enrollment for User ID: ${targetUser.id}`);
409	
410	        // 1. Send the images to the Python face AI service (with a timeout so we never hang).
411	        //    FACE_AI_URL is a BASE url (e.g. http://127.0.0.1:8501); endpoint paths are appended.
412	        const faceAiUrl = process.env.FACE_AI_URL || 'http://127.0.0.1:8501';
413	        //    Images live only in request memory (browser → Node → FastAPI); they are
414	        //    never written to the DB, disk, cloud storage, or logs. Only the resulting
415	        //    protected biometric template is stored against the User ID.
416	        const pythonResponse = await axios.post(`${faceAiUrl}/api/encode-faces`, {
417	            front: images.front,
418	            left: images.left,
419	            right: images.right
420	        }, {
421	            timeout: 20000,
422	            headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
423	        });
424	
425	        const faceVector = pythonResponse.data?.vector; // The 512-number array
426	
427	        // Guard against an unexpected/empty AI response so we don't store junk.
428	        if (!Array.isArray(faceVector) || faceVector.length === 0) {
429	            return res.status(502).json({ error: "Unexpected response from facial recognition service." });
430	        }
431	
432	        // 2. Save to PostgreSQL using Sequelize
433	        await User.update(
434	            { faceVector, isEnrolled: true },
435	            { where: { id: targetUser.id } }
436	        );
437	
438	        // 3. Ask the AI service to reload its in-memory known-face cache so the newly
439	        //    enrolled face is recognised immediately on V-Patrol/Gate Scanner — no AI
440	        //    restart needed. A refresh failure must NOT fail the enrolment (the cache
441	        //    reloads on the next AI-service restart anyway).
442	        try {
443	            await axios.get(`${faceAiUrl}/refresh`, {
444	                timeout: 5000,
445	                headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
446	            });
447	            return res.status(200).json({ message: "Biometric enrollment successful" });
448	        } catch (refreshErr) {
449	            console.warn("AI face-cache refresh failed (enrolment still saved):", refreshErr.message);
450	            return res.status(200).json({ message: "Face enrolled, AI cache refresh pending." });
451	        }
452	
453	    } catch (error) {
454	        // Developer log only.
455	        console.error("Enrollment Error:", error.response ? error.response.data : error.message);
456	
457	        // AI service offline / unreachable / timed out → 503 (clear, not a generic 500).
458	        const isConnError = !error.response &&
459	            ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(error.code);
460	        if (isConnError) {
461	            return res.status(503).json({ error: "Facial recognition service is offline. Please try again shortly." });
462	        }
463	
464	        // AI service replied with an error (e.g. 400 "No face detected") → forward its status.
465	        if (error.response) {
466	            const status = error.response.status === 400 ? 400 : 502;
467	            return res.status(status).json({
468	                error: error.response.data?.detail || "Failed to generate biometric vector."
469	            });
470	        }
471	
472	        // Anything else → safe generic 500.
473	        res.status(500).json({ error: "Failed to generate biometric vector." });
474	    }
475	});
476	
477	// --- MANUAL USER CREATION (role-gated, additive) ---
478	// Role rules (enforced server-side):
479	//   FM     -> may create Tenant accounts
480	//   Tenant -> may create Staff accounts (linked to that Tenant via managerId)
481	//   Staff / Public -> cannot create users
482	//   No one can create FM accounts through this flow.
483	// The invite-code self-registration flow (POST /register) remains unchanged as an alternative.
484	router.post('/manual-create', authenticateToken, async (req, res) => {
485	    try {
486	        const creatorRole = req.user.role;
487	
488	        let targetRole;
489	        if (creatorRole === 'FM') targetRole = 'Tenant';
490	        else if (creatorRole === 'Tenant') targetRole = 'Staff';
491	        else return res.status(403).json({ errors: ["You do not have permission to add users."] });
492	
493	        // If the client sends an explicit role, it must match what this creator may create.
