  Object.keys(DB.users).forEach((k) => delete DB.users[k]);
  DB.users[1] = makeUser({ id: 1, name: "Fatimah FM", email: "fm@x.com", role: "FM" });
  DB.users[2] = makeUser({ id: 2, name: "Tina Tenant", email: "tenant@x.com", role: "Tenant" });
